`timescale 1ns / 1ps
`default_nettype none

// sync_fifo: parameterizable synchronous FIFO with first-word fall-through.
// Implements microarchitecture.md for the interface in interface_spec.md.
//  * Storage `mem` is datapath: not reset, written only outside reset.
//  * Pointers wrap by comparing against LAST, so DEPTH need not be a power of 2.
//  * Occupancy is an explicit counter; full/empty are compares on a register.
//  * Requests are gated by the flags: write while full and read while empty
//    are dropped with no side effect.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);
    localparam integer PW   = $clog2(DEPTH);
    localparam integer CW   = $clog2(DEPTH+1);
    localparam integer LAST = DEPTH - 1;

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [PW-1:0]    wr_ptr;
    reg [PW-1:0]    rd_ptr;
    reg [CW-1:0]    count_q;

    wire wr_acc;
    wire rd_acc;

    assign full    = (count_q == DEPTH[CW-1:0]);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign wr_acc  = wr_en && !full;
    assign rd_acc  = rd_en && !empty;
    assign rd_data = mem[rd_ptr];

    // Control: pointers and occupancy, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            if (wr_acc) begin
                if (wr_ptr == LAST[PW-1:0]) begin
                    wr_ptr <= {PW{1'b0}};
                end else begin
                    wr_ptr <= wr_ptr + 1'b1;
                end
            end
            if (rd_acc) begin
                if (rd_ptr == LAST[PW-1:0]) begin
                    rd_ptr <= {PW{1'b0}};
                end else begin
                    rd_ptr <= rd_ptr + 1'b1;
                end
            end
            case ({wr_acc, rd_acc})
                2'b10:   count_q <= count_q + 1'b1;
                2'b01:   count_q <= count_q - 1'b1;
                default: count_q <= count_q;
            endcase
        end
    end

    // Datapath: storage, not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven by this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [CW:0] f_sum  = {1'b0, count_q} + {{(CW+1-PW){1'b0}}, rd_ptr};
    wire [CW:0] f_wrap = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;

    always @(*) begin
        if (f_past_valid) begin
            assert (full  == (count_q == DEPTH[CW-1:0]));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (count_q <= DEPTH[CW-1:0]);
            assert (wr_ptr <= LAST[PW-1:0]);
            assert (rd_ptr <= LAST[PW-1:0]);
            assert (wr_ptr == f_wrap[PW-1:0]);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr == {PW{1'b0}});
                assert (rd_ptr == {PW{1'b0}});
            end else begin
                if ($past(wr_acc) && !$past(rd_acc))
                    assert (count_q == $past(count_q) + 1'b1);
                if (!$past(wr_acc) && $past(rd_acc))
                    assert (count_q == $past(count_q) - 1'b1);
                if ($past(wr_acc) == $past(rd_acc))
                    assert (count_q == $past(count_q));
                if ($past(wr_en) && $past(full))
                    assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en) && $past(empty))
                    assert (rd_ptr == $past(rd_ptr));
            end
        end
    end
`endif

endmodule

`default_nettype wire
