`timescale 1ns / 1ps

// Self-checking testbench for sync_fifo.
// Two FIFOs (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) receive the same stimulus;
// each is checked on every rising edge against a reference queue.
module sync_fifo_tb;
    reg        clk;
    reg        rst_n;
    reg        wr_en;
    reg        rd_en;
    reg [31:0] stim_data;

    reg [8*64-1:0] nonce;
    integer passed;
    integer failed;
    integer total_passed;
    integer total_failed;

    sync_fifo_checker #(.DEPTH(8), .WIDTH(8)) u_c8 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en), .stim_data(stim_data)
    );

    sync_fifo_checker #(.DEPTH(5), .WIDTH(12)) u_c5 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en), .stim_data(stim_data)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Drive one cycle of requests on the falling edge.
    task drive;
        input w;
        input r;
        begin
            @(negedge clk);
            wr_en     = w;
            rd_en     = r;
            stim_data = $random;
        end
    endtask

    task drive_n;
        input w;
        input r;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) drive(w, r);
        end
    endtask

    task drive_rand;
        input integer n;
        input integer wb;
        input integer rb;
        integer k;
        reg w;
        reg r;
        begin
            for (k = 0; k < n; k = k + 1) begin
                w = (({$random} % 100) < wb);
                r = (({$random} % 100) < rb);
                drive(w, r);
            end
        end
    endtask

    task cov;
        input integer hits;
        input [8*40-1:0] name;
        begin
            if (hits > 0) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("coverage hole: %0s was never reached", name);
            end
        end
    endtask

    initial begin
        rst_n     = 1'b0;
        wr_en     = 1'b0;
        rd_en     = 1'b0;
        stim_data = 32'd0;
        passed    = 0;
        failed    = 0;
        nonce     = "none";
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";

        // Reset, with requests that must be ignored.
        drive(1'b1, 1'b1);
        drive(1'b1, 1'b0);
        drive(1'b0, 1'b1);
        drive(1'b0, 1'b0); rst_n = 1'b1;

        // Fill to full, then writes while full.
        drive_n(1'b1, 1'b0, 10);
        // Write and read together when full, then in between.
        drive_n(1'b1, 1'b1, 3);
        drive_n(1'b1, 1'b0, 3);
        // Drain to empty, then reads while empty.
        drive_n(1'b0, 1'b1, 12);
        // Write and read together when empty, then in between.
        drive_n(1'b1, 1'b1, 4);
        drive_n(1'b0, 1'b1, 6);

        // Reset during traffic with entries held.
        drive_n(1'b1, 1'b0, 3);
        drive(1'b1, 1'b1); rst_n = 1'b0;
        drive(1'b1, 1'b0);
        drive(1'b0, 1'b1); rst_n = 1'b1;

        // Random traffic with varying bias (pointer wrap-around, all regions).
        drive_rand(500, 50, 50);
        drive_rand(300, 80, 30);
        drive_rand(300, 30, 80);
        drive_rand(200, 60, 60);

        // Reset in the middle of random traffic.
        drive_rand(20, 90, 10);
        drive(1'b1, 1'b1); rst_n = 1'b0;
        drive(1'b1, 1'b1); rst_n = 1'b1;
        drive_rand(400, 55, 50);

        // Drain and settle.
        drive_n(1'b0, 1'b1, 12);
        drive(1'b0, 1'b0);
        drive(1'b0, 1'b0);
        @(negedge clk);

        // Coverage: every corner case in the interface spec must be reached.
        cov(u_c8.cov_fill,        "D8 filled to full");
        cov(u_c8.cov_wr_full,     "D8 write while full");
        cov(u_c8.cov_drain,       "D8 drained to empty");
        cov(u_c8.cov_rd_empty,    "D8 read while empty");
        cov(u_c8.cov_both_empty,  "D8 write+read when empty");
        cov(u_c8.cov_both_full,   "D8 write+read when full");
        cov(u_c8.cov_both_mid,    "D8 write+read in between");
        cov(u_c8.cov_rd_wrap,     "D8 read pointer wrap");
        cov(u_c8.cov_wr_wrap,     "D8 write pointer wrap");
        cov(u_c8.cov_rst_traffic, "D8 reset during traffic");
        cov(u_c5.cov_fill,        "D5 filled to full");
        cov(u_c5.cov_wr_full,     "D5 write while full");
        cov(u_c5.cov_drain,       "D5 drained to empty");
        cov(u_c5.cov_rd_empty,    "D5 read while empty");
        cov(u_c5.cov_both_empty,  "D5 write+read when empty");
        cov(u_c5.cov_both_full,   "D5 write+read when full");
        cov(u_c5.cov_both_mid,    "D5 write+read in between");
        cov(u_c5.cov_rd_wrap,     "D5 read pointer wrap");
        cov(u_c5.cov_wr_wrap,     "D5 write pointer wrap");
        cov(u_c5.cov_rst_traffic, "D5 reset during traffic");

        total_passed = passed + u_c8.passed + u_c5.passed;
        total_failed = failed + u_c8.failed + u_c5.failed;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_passed, total_failed);
        $finish;
    end
endmodule

// One DUT plus its reference queue, checked on every rising edge.
module sync_fifo_checker #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input wire        clk,
    input wire        rst_n,
    input wire        wr_en,
    input wire        rd_en,
    input wire [31:0] stim_data
);
    localparam integer CW = $clog2(DEPTH+1);

    wire [WIDTH-1:0] wr_data = stim_data[WIDTH-1:0];
    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) u_dut (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full),
        .rd_en(rd_en), .rd_data(rd_data), .empty(empty),
        .count(count)
    );

    reg [WIDTH-1:0] model_q [0:DEPTH-1];
    integer m_head;
    integer m_count;
    integer m_tail;
    reg     model_valid;
    reg     m_wr_acc;
    reg     m_rd_acc;

    integer passed;
    integer failed;
    integer cov_fill, cov_wr_full, cov_drain, cov_rd_empty;
    integer cov_both_empty, cov_both_full, cov_both_mid;
    integer cov_rd_wrap, cov_wr_wrap, cov_rst_traffic;

    initial begin
        model_valid     = 1'b0;
        m_head          = 0;
        m_count         = 0;
        m_tail          = 0;
        m_wr_acc        = 1'b0;
        m_rd_acc        = 1'b0;
        passed          = 0;
        failed          = 0;
        cov_fill        = 0;
        cov_wr_full     = 0;
        cov_drain       = 0;
        cov_rd_empty    = 0;
        cov_both_empty  = 0;
        cov_both_full   = 0;
        cov_both_mid    = 0;
        cov_rd_wrap     = 0;
        cov_wr_wrap     = 0;
        cov_rst_traffic = 0;
    end

    always @(posedge clk) begin
        // Check the state after the previous edge (DUT outputs are pre-NBA here).
        if (model_valid) begin
            if (count === m_count[CW-1:0]) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("DEPTH=%0d WIDTH=%0d t=%0t: count=%0d expected %0d",
                       DEPTH, WIDTH, $time, count, m_count);
            end
            if (full === (m_count == DEPTH)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("DEPTH=%0d WIDTH=%0d t=%0t: full=%b expected %b",
                       DEPTH, WIDTH, $time, full, (m_count == DEPTH));
            end
            if (empty === (m_count == 0)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("DEPTH=%0d WIDTH=%0d t=%0t: empty=%b expected %b",
                       DEPTH, WIDTH, $time, empty, (m_count == 0));
            end
            if (m_count > 0) begin
                if (rd_data === model_q[m_head]) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("DEPTH=%0d WIDTH=%0d t=%0t: rd_data=%h expected %h",
                           DEPTH, WIDTH, $time, rd_data, model_q[m_head]);
                end
            end
        end

        // Advance the reference model.
        if (!rst_n) begin
            if (model_valid && (m_count > 0)) cov_rst_traffic = cov_rst_traffic + 1;
            m_head      = 0;
            m_count     = 0;
            model_valid = 1'b1;
        end else if (model_valid) begin
            m_wr_acc = wr_en && (m_count != DEPTH);
            m_rd_acc = rd_en && (m_count != 0);

            if (wr_en && (m_count == DEPTH)) cov_wr_full = cov_wr_full + 1;
            if (rd_en && (m_count == 0)) cov_rd_empty = cov_rd_empty + 1;
            if (wr_en && rd_en && (m_count == 0)) cov_both_empty = cov_both_empty + 1;
            if (wr_en && rd_en && (m_count == DEPTH)) cov_both_full = cov_both_full + 1;
            if (wr_en && rd_en && (m_count > 0) && (m_count < DEPTH))
                cov_both_mid = cov_both_mid + 1;

            m_tail = (m_head + m_count) % DEPTH;
            if (m_wr_acc) begin
                model_q[m_tail] = wr_data;
                if (m_tail == DEPTH - 1) cov_wr_wrap = cov_wr_wrap + 1;
            end
            if (m_rd_acc) begin
                if (m_head == DEPTH - 1) cov_rd_wrap = cov_rd_wrap + 1;
                m_head = (m_head + 1) % DEPTH;
            end
            m_count = m_count + (m_wr_acc ? 1 : 0) - (m_rd_acc ? 1 : 0);

            if (m_wr_acc && !m_rd_acc && (m_count == DEPTH)) cov_fill = cov_fill + 1;
            if (m_rd_acc && !m_wr_acc && (m_count == 0)) cov_drain = cov_drain + 1;
        end
    end
endmodule
